function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.report}"/></svg>`}
function brand(cls=''){return `<div class="brand ${cls}"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span><span class="wordmark">하루금융<span style="font-size:10px;font-weight:500;color:#8fa58d;margin-left:5px">LAB</span></span></div>`}
const number=n=>Math.round(n||0).toLocaleString('ko-KR'), billions=n=>number(n)+'억', pct=n=>(n>0?'+':'')+Number(n||0).toFixed(1)+'%', sectorColors={'기술':['#e8f1e9','#628b67'],'항공':['#ebf0f6','#758fad'],'식품':['#f7f0e2','#b39966'],'의료·제약':['#f1ecf5','#9983ad'],'미래사업':['#e8f2f1','#6b9b92']};
