async function api(url,opt={}){if(S?.demo){if(url.startsWith('/history/'))return S.histories[url.split('/').pop()]||[];if(opt.method&&opt.method!=='GET')throw Error('읽기 전용 체험입니다. 게임방에 참가하면 거래와 기록을 할 수 있어요.')}return legacyViews.api(url,opt)}
async function startDemo(){try{S=await legacyViews.api('/demo');tab='home';render();window.scrollTo(0,0)}catch(e){toast(e.message)}}
function exitDemo(){S=null;tab='home';render()}
function companyAvatar(a){let c=sectorColors[a?.sector]||['#edf2ea','#7a9170'];return `<span class="company-avatar" style="--tile:${c[0]};--tile-ink:${c[1]}">${esc(a?.name?.slice(0,1)||'H')}</span>`}
function latestReport(id,q=null){return (S.reports||[]).find(r=>r.asset===id&&(q===null||r.quarter===q))}
function forecastFor(id,q){return (S.forecasts||[]).find(r=>r.asset===id&&r.quarter===q)}
function reportBadge(r){let v=r?.market_verdict||r?.verdict;return `<span class="verdict ${v==='예상 상회'?'beat':v==='예상 하회'?'miss':''}">${esc(v||'발표 대기')}</span>`}
function currentView(){return S?.role==='admin'&&tab==='preview'?previewTab:tab}
function isPreview(){return S?.role==='admin'&&tab==='preview'}
function myData(){return isPreview()&&previewData?previewData:S}
function emptyState(text){return `<div class="empty">${esc(text)}</div>`}
function smallLink(label,action){return `<button class="text-btn" onclick="${action}">${label} ${icon('chevron')}</button>`}

function authView(){
 let modes=[['join','학생 참가'],['admin','교사 로그인'],['create','방 만들기']];
 return `<div class="auth-shell"><section class="auth-hero">${brand()}<div class="eyebrow">CLASSROOM INVESTMENT LAB</div><h1>뉴스를 읽고,<br>기업의 내일에<br><em>투자하다.</em></h1><p>뉴스 속 단서를 찾고, 분기 실적으로 확인하는 투자.<br>오늘의 선택이 내일의 배움이 되는 우리 반 금융시장.</p><div class="auth-pills"><span>가상의 1년, 24일</span><span>20개 가상 기업</span><span>4번의 분기 실적</span></div><div class="preview-finance" aria-label="기업 실적을 비교하는 화면 예시"><div class="preview-head"><div class="preview-company"><span class="company-avatar">한</span><div>한빛전자<div class="sub">기업 분석 리포트 · 화면 예시</div></div></div><span class="certainty fact">실적 비교</span></div><h3>기대를 숫자로 확인해요.</h3><span class="sub">뉴스 → 투자 가설 → 실적 발표 → 돌아보기</span><div class="preview-bars">${[[27,36],[36,46],[42,59],[48,73]].map(([a,b])=>`<div><i style="height:${a}px"></i><i style="height:${b}px"></i></div>`).join('')}</div><div class="preview-legend"><span><i></i>시장 예상</span><span><i class="actual"></i>발표 실적</span></div></div><div class="auth-footer">HARU FINANCE — LEARN TO THINK, BEFORE YOU INVEST.</div></section><section class="auth-form-wrap"><div class="auth-form">${brand('auth-mobile-title')}<div class="eyebrow">WELCOME TO YOUR CLASSROOM</div><h2>${authMode==='create'?'우리 반 시장을 열어요.':authMode==='admin'?'수업을 이어가 볼까요?':'오늘의 투자를 시작해요.'}</h2><p class="sub">${authMode==='create'?'교사만의 비밀번호로 새 게임방을 만드세요.':authMode==='admin'?'게임방 코드와 교사용 비밀번호를 입력하세요.':'게임방 코드와 이름, 개인 PIN으로 입장하세요.'}</p><div class="seg">${modes.map(([k,v])=>`<button type="button" class="${authMode===k?'active':''}" onclick="authMode='${k}';render()">${v}</button>`).join('')}</div><form onsubmit="event.preventDefault();submitAuth()">${authMode==='create'?`<label for="roomName">게임방 이름</label><input class="input" id="roomName" maxlength="50" value="우리 반 투자 연구소" required><label for="pw">교사용 비밀번호</label><input class="input" id="pw" type="password" minlength="4" autocomplete="new-password" placeholder="4자 이상 입력" required><label for="startCash">학생 시작 자금</label><input class="input" id="startCash" type="number" value="100000" min="1000" max="100000000" required>`:`<label for="code">게임방 코드</label><input class="input" id="code" maxlength="6" value="${esc(joinCode)}" placeholder="6자리 게임방 코드" style="text-transform:uppercase;letter-spacing:2px" autocomplete="off" required>${authMode==='join'?`<label for="nickname">이름 또는 별명</label><input class="input" id="nickname" maxlength="24" placeholder="수업에서 사용하는 이름" autocomplete="username" required><label for="pin">개인 PIN</label><input class="input" id="pin" type="password" minlength="4" placeholder="기억할 PIN, 4자 이상" autocomplete="current-password" required>`:`<label for="pw">교사용 비밀번호</label><input class="input" id="pw" type="password" minlength="4" autocomplete="current-password" placeholder="교사용 비밀번호" required>`}`}<button type="submit" class="btn submit">${authMode==='create'?'게임방 만들기':authMode==='admin'?'교사 운영센터 입장':'투자 연구소 입장'} ${icon('arrow')}</button></form><button type="button" class="btn secondary" style="width:100%;margin-top:10px" onclick="startDemo()">${icon('eye')} 학생 화면 미리 체험하기</button><p class="auth-hint">${authMode==='join'?'처음 참가하면 계정이 만들어져요.<br>다시 접속할 때도 같은 이름과 PIN을 사용하세요.':'학생은 QR 코드와 게임방 코드로 쉽게 참가할 수 있어요.'}</p><div class="auth-small">${icon('shield')} 실제 돈을 사용하지 않는 교육용 가상 금융시장</div></div></section></div>`
}

const studentMenu=[['home','오늘의 투자','home'],['news','뉴스룸','news'],['earnings','기업 실적','report'],['market','투자시장','market'],['portfolio','내 자산','portfolio'],['journal','투자 노트','journal'],['bank','은행','bank'],['orders','거래 기록','clock']];
const teacherMenu=[['home','수업 운영','home'],['news','뉴스룸','news'],['earnings','기업 실적','report'],['market','투자시장','market'],['preview','학생 화면','eye'],['players','학생·학습 현황','people'],['orders','거래·투자 근거','journal'],['admin','진행·설정','settings']];
function head(){
 let adminMode=S.role==='admin',r=S.room,menu=adminMode?teacherMenu:studentMenu;
 let names={home:adminMode?'우리 반 투자 연구소':'오늘의 투자',news:'뉴스룸',earnings:'기업 실적센터',market:'투자시장',portfolio:'내 자산',journal:'나의 투자 노트',bank:'우리 반 은행',orders:adminMode?'거래와 투자 근거':'나의 거래 기록',preview:'학생 화면 미리보기',players:'학생·학습 현황',admin:'수업 진행과 설정',detail:asset(selected)?.name||'기업 분석'};
 let subtitles={home:adminMode?'숫자보다 먼저, 학생들의 판단 과정을 살펴보세요.':'뉴스를 읽고, 기업을 살피고, 나만의 판단을 기록해 보세요.',news:'새로운 소식과 이미 확인된 사실을 구분해 읽어 보세요.',earnings:'기대했던 이야기가 실제 매출과 이익으로 이어졌을까요?',market:'주가의 움직임 뒤에 있는 기업과 산업을 살펴보세요.',portfolio:'오늘의 선택이 모여 만든 나의 자산입니다.',journal:'어떤 근거로 판단했는지, 무엇을 배웠는지 남겨 보세요.',players:'기사 열람, 근거 있는 거래, 투자 노트와 돌아보기 현황입니다.'};
 let next=(S.calendar||[]).find(q=>!q.released&&q.day>=r.day),finished=r.phase==='finished';
 return `<aside class="side">${brand()}<div class="side-label">${adminMode?'TEACHER WORKSPACE':'MY INVESTMENT LAB'}</div><nav class="side-nav" aria-label="주 메뉴">${menu.map(([k,v,i])=>`<button class="${tab===k||(k==='market'&&tab==='detail')?'active':''}" onclick="go('${k}')" ${tab===k?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${v}</span>${k==='earnings'&&S.calendar?.some(q=>q.released&&q.day===r.day)?'<span class="nav-badge">NEW</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="room-mini"><div class="sub">${esc(r.name)}</div><div class="room-code">${esc(r.code)}</div><div class="sub">24일 동안 경험하는 가상의 1년</div></div><div class="side-user"><div class="avatar">${adminMode?'T':esc(S.player.name.slice(0,1))}</div><div><b>${adminMode?'선생님':esc(S.player.name)}</b><div class="sub">${adminMode?'TEACHER':'STUDENT'} ACCOUNT</div></div><button class="logout" aria-label="로그아웃" onclick="logout()">${icon('logout')}</button></div></div></aside><div class="workspace"><div class="topbar"><div class="crumb">우리 반 투자 연구소 ${icon('chevron')} <strong>${esc(names[tab]||'기업 분석')}</strong></div>${brand('mobile-brand')}<div class="top-meta"><span class="sub">${esc(r.name)}</span><span class="live"><i></i>${finished?'결산 완료':r.phase==='trading'?'거래 중':'장 마감'}</span><button class="text-btn" title="새로고침" aria-label="새로고침" onclick="refresh()">${icon('refresh')}</button><button class="logout mobile-brand" aria-label="로그아웃" onclick="logout()">${icon('logout')}</button></div></div><main class="content"><div class="page-title"><div><h1>${esc(names[tab]||'기업 분석')}</h1><p class="sub">${subtitles[tab]||'정보를 비교하고 투자 이유를 생각해 보세요.'}</p></div><div class="title-meta"><div class="eyebrow">VIRTUAL YEAR · ${Math.round(r.day/24*100)}%</div><div class="period">${Math.ceil(r.day/6)}분기 <span style="color:#aec0ab;padding:0 5px">/</span> ${r.day}일차</div>${next?`<span class="sub" style="font-size:9px">다음 실적 ${next.day}일차</span>`:''}</div></div>${S.demo?'<div class="notice" style="margin-bottom:16px">6일차 학생 화면을 보여 주는 읽기 전용 체험입니다. 직접 거래하려면 게임방에 참가해 주세요. <button class="text-btn" onclick="exitDemo()">입장 화면으로 →</button></div>':adminMode?'':dayFinishPanel()}<div id="page"></div></main></div>`;
}
function dayFinishPanel(){let ready=S.player?.day_ready;return `<div class="daily-done ${ready?'done':''}"><div><b>${S.room.phase==='finished'?'24일 동안의 투자 여정이 끝났어요.':ready?'오늘의 투자 선택을 마쳤어요.':'오늘의 판단을 마쳤나요?'}</b> <span class="sub">${ready?'선생님이 다음 거래일을 열 때까지 기다려 주세요.':'거래하지 않고 기다리는 것도 좋은 선택이에요.'}</span></div>${S.room.phase==='trading'?`<button class="btn ${ready?'ghost':'secondary'} sm" onclick="setReady(${!ready})">${icon(ready?'refresh':'check')}${ready?'선택 다시 하기':'하루 마감'}</button>`:`<span class="tag">${S.room.phase==='finished'?'결산 완료':'교사가 다음 날을 준비 중'}</span>`}</div>`}
async function setReady(ready){try{await api('/day/'+(ready?'complete':'reopen'),{method:'POST'});toast(ready?'오늘 선택 완료를 선생님께 알렸어요.':'다시 선택할 수 있어요.');await refresh()}catch(e){toast(e.message)}}
function go(k){closeModal();if(isPreview()&&['home','market','detail','bank','portfolio','orders','news','earnings','journal'].includes(k)){previewTab=k}else{tab=k}render();window.scrollTo({top:0,behavior:'smooth'})}
function stat(label,value,foot,featured=false,ic='wallet'){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${icon(ic)}${label}</div><strong>${value}</strong><div class="stat-foot">${foot}</div>${featured?`<span class="micro">${icon('market')}</span>`:''}</div>`}
function calendarCards(){return `<div class="earn-date">${(S.calendar||[]).map(q=>`<div class="${q.released?'done':q.day>=S.room.day&&q.day===((S.calendar||[]).find(x=>!x.released&&x.day>=S.room.day)||{}).day?'current':''}"><span>QUARTER ${q.quarter}</span><b>${q.day}일차</b><small>${q.released?'✓ 실적 공개':q.day<S.room.day?'기록 없음':q.day===S.room.day?'오늘 발표':'발표 예정'}</small></div>`).join('')}</div>`}
function sectorBoard(){return `<div class="sector-grid">${['TECH','AIR','FOOD','HEAL','FUTR'].map(id=>{let a=asset(id);return `<button class="sector-mini" onclick="marketSector='${esc(a.sector)}';marketFilter='stock';go('market')"><span>${esc(a.sector)}</span><b class="${a.change>=0?'up':'down'}">${pct(a.change)}</b><div class="sector-line ${a.change<0?'negative':''}"><i style="width:${Math.min(100,25+Math.abs(a.change)*10)}%"></i></div></button>`}).join('')}</div>`}
function focusRow(a){return `<div class="focus-row" role="button" tabindex="0" onclick="detail('${a.id}')" onkeydown="if(event.key==='Enter')detail('${a.id}')">${companyAvatar(a)}<div class="desc"><b>${esc(a.name)}</b><p>${esc(a.sector)} · ${risk[a.risk]}</p></div><div class="right"><b>${money(a.price)}</b><div class="sub ${a.change>=0?'up':'down'}">${pct(a.change)}</div></div></div>`}
function playerHome(){
 let p=S.player,today=S.news.filter(n=>n.day===S.room.day),watch=(S.watchlist||[]).map(asset).filter(Boolean),focus=watch.length?watch.slice(0,4):S.assets.filter(a=>a.type==='stock').sort((a,b)=>Math.abs(b.change)-Math.abs(a.change)).slice(0,4),l=S.learning||{},q=Math.ceil(S.room.day/6),days=q*6-S.room.day;
 return `<div class="overview">${stat('나의 총자산',money(p.net),`시작 이후 <span>${p.profit>=0?'+':''}${money(p.profit)}</span>`,true)}${stat('투자 가능 현금',money(p.cash),`투자·예금에 사용할 수 있는 금액`,false,'bank')}${stat('투자 수익률',`<span class="${p.profit>=0?'up':'down'}">${pct(p.profit/S.room.start_cash*100)}</span>`,`${S.holdings.length}개 상품 보유 · ${l.note_count||0}개의 투자 노트`,false,'market')}</div>${npcPanel()}<div class="dashboard-grid"><div class="stack"><div><div class="lesson-hero"><div><div class="eyebrow">TODAY'S INVESTMENT QUESTION</div><h2>${days===0?'기대했던 성장이 숫자로 확인됐을까요?':'이 뉴스가 회사의 이익도 늘려 줄까요?'}</h2><p>${days===0?'오늘 공개된 분기 실적에서 실제 결과와 사전 예상치를 비교해 보세요.':'매출이 늘어나는 소식과 비용이 늘어나는 소식을 함께 살펴보세요.'}</p><div class="daily-path"><b>01</b> 뉴스 읽기 ${icon('chevron')} <b>02</b> 실적 비교 ${icon('chevron')} <b>03</b> 판단 기록</div></div><div class="lesson-number">0${q}</div></div><div class="card"><div class="section-title"><h2>오늘의 뉴스 브리핑</h2>${smallLink('전체 뉴스',"go('news')")}</div>${newsCards(selectHighlights(today),true)}</div></div><div class="card"><div class="section-title"><h2>산업별 시장 흐름</h2><span class="sub">오늘 · 섹터 ETF 기준</span></div>${sectorBoard()}</div></div><div class="stack"><div class="card"><div class="section-title"><h2>분기 실적 캘린더</h2>${icon('calendar')}</div><p class="sub">6일마다 기업의 성적표가 공개돼요.</p>${calendarCards()}<div class="line"></div><div class="flex"><span class="sub">예상치와 실제 결과를 비교해 보세요.</span>${smallLink('실적센터',"go('earnings')")}</div></div><div class="card"><div class="section-title"><h2>${watch.length?'내가 지켜보는 기업':'오늘 살펴볼 기업'}</h2>${smallLink('시장',"go('market')")}</div>${focus.map(focusRow).join('')}<p class="hint no-margin">기업 화면의 ☆를 누르면 관심 목록에 담을 수 있어요.</p></div><div class="research-prompt"><span class="eyebrow">MY INVESTMENT NOTE</span><p>어떤 뉴스를 믿었나요?<br>예상과 다르게 흘러가면 어떻게 할까요?</p><button class="text-btn" style="padding:10px 0 0" onclick="go('journal')">나의 생각 기록하기 ${icon('arrow')}</button></div></div></div>`
}

function horizonTag(n){if(!['company','followup'].includes(n.kind))return '';let labels={short:'단기',next_quarter:'다음 분기',year_end:'연말'},k=n.horizon||'short';return `<span class="horizon-tag ${k}">${labels[k]||'단기'} 영향</span>`}
function horizonDetails(n){if(!['company','followup'].includes(n.kind))return '';let labels={short:'단기 운영',next_quarter:'다음 분기 사업',year_end:'연말 사업'},k=n.horizon||'short';return `<div class="horizon-detail"><div class="flex"><b>${icon('calendar')} ${labels[k]||'단기 운영'} 소식</b>${horizonTag(n)}</div><p>${n.expected_start?`실적 영향 예상 기간: <b>${n.expected_start}~${n.expected_end||n.expected_start}일차</b><br>`:''}기사에 대한 기대와 실적에 반영되는 시점은 달라요. 일정은 바뀔 수 있고 사업이 예상과 다르게 진행될 수 있어요.${k!=='short'?'<br>준비·연구 비용이 먼저 발생해 초기 이익이 줄 수도 있어요.':''}</p></div>`}
function filterHorizon(k){newsHorizon=k;if(k==='next_quarter'||k==='year_end')newsScope='all';render()}
function projectBoard(aid=null){
 let my=new Set([...(S.watchlist||[]),...(S.holdings||[]).map(h=>h.asset)]);
 let list=(S.events||[]).filter(e=>e.horizon&&e.horizon!=='short'&&e.expected_end>=S.room.day&&(!aid||e.asset===aid)&&(!newsFocus||e.asset===newsFocus)&&(newsSector==='전체'||asset(e.asset)?.sector===newsSector)&&(newsMode!=='mine'||my.has(e.asset))&&(newsHorizon==='all'||newsHorizon===e.horizon)).sort((a,b)=>a.expected_start-b.expected_start||a.start_day-b.start_day).slice(0,aid?3:6);
 if(!list.length)return '';
 return `<div class="project-board"><div class="section-title"><h2>${aid?'이 기업의 장기 사업':'기억해 둘 장기 뉴스'}</h2><span class="sub">예상 기간 · 확정 수익 아님</span></div><div class="project-grid">${list.map(e=>{let first=S.news.filter(n=>n.event_id===e.id).sort((a,b)=>a.day-b.day||a.id-b.id)[0],done=['confirmed','reversed'].includes(e.stage),label=e.stage==='delayed'?'일정 조정':e.stage==='reversed'?'예상과 다른 결과':done?'영업 영향 중':'진행 확인 중';return `<div class="project-item"><div class="flex"><span class="horizon-tag ${e.horizon}">${e.horizon==='year_end'?'연말':'다음 분기'}</span><span class="sub">${label}</span></div><b>${esc(asset(e.asset)?.name)} · ${esc(e.title)}</b><p>${e.start_day}일차 첫 보도 → ${e.expected_start}~${e.expected_end}일차 영향 예상</p>${first?`<button class="text-btn" onclick="openArticle(${first.id})">처음 기사 다시 읽기 ${icon('arrow')}</button>`:''}</div>`}).join('')}</div></div>`
}
function benchmarkCard(){if(!S.player)return '';let rate=S.benchmark?.deposit_rate??.1,progress=S.benchmark?.progress_rate??rate*(S.room.day-1)/23,own=S.player.profit/S.room.start_cash,diff=(own-progress)*100;return `<div class="card benchmark-card"><div class="section-title"><h2>24일 예금 10%와 나의 투자</h2><span class="sub">같은 시작 자금 기준</span></div><div class="benchmark-grid"><div><span>예금 만기 수익률</span><strong>+${(rate*100).toFixed(1)}%</strong><small>${money(S.room.start_cash)} → ${money(S.room.start_cash*(1+rate))}</small></div><div><span>오늘 진행률의 예금 비교선</span><strong>${pct(progress*100)}</strong><small>${S.room.day}일차 · 만기까지의 기간으로 나눈 값</small></div><div><span>나의 투자 수익률</span><strong class="${own>=0?'up':'down'}">${pct(own*100)}</strong><small>오늘 비교선보다 ${Math.abs(diff).toFixed(1)}%p ${diff>=0?'높아요':'낮아요'}</small></div></div><p class="hint no-margin" style="margin-top:15px">비교선은 예금 10%를 게임 진행률에 맞춰 나눈 참고선이며, 실제 예금 이자는 만기에 지급됩니다. 투자 수익은 현금·보유 상품·예금을 합쳐 계산하고 교사의 현금 지급·차감은 제외해요.</p></div>`}
function portfolio(){return benchmarkCard()+basePortfolio()}
function certaintyTag(n){let fact=n.certainty?.includes('확인')||n.certainty?.includes('현황');return `<span class="certainty ${n.kind==='earnings'?'earn':fact?'fact':''}">${esc(n.certainty||'보도')}</span>`}
function newsCards(arr,compact=false){return arr.map(n=>{let read=(S.read_ids||[]).includes(n.id),rel=(n.related_assets||[]).map(id=>asset(id)).filter(Boolean);let target=asset(n.sector);return `<article class="article-card ${compact?'compact':''}" tabindex="0" role="button" onclick="openArticle(${n.id})" onkeydown="if(event.key==='Enter')openArticle(${n.id})"><div class="article-meta"><div class="article-source"><i></i>${esc(n.source||'하루경제')}<span>· ${n.day}일차</span></div>${certaintyTag(n)}</div><h3>${esc(n.title)}</h3>${compact?'':`<p>${esc(n.body)}</p>`}<div class="article-footer">${rel.slice(0,2).map(a=>`<button onclick="event.stopPropagation();detail('${a.id}')">${esc(a.name)}</button>`).join('')}${!rel.length?`<span>${target?esc(target.name):esc(n.sector)}</span>`:''}${horizonTag(n)}${n.kind==='followup'?'<span>후속 보도</span>':''}<span style="margin-left:auto" class="${read?'read-tick':''}">${read?'✓ 열람함':'기사 읽기 ↗'}</span></div></article>`}).join('')||emptyState('이 조건에 해당하는 기사가 아직 없어요.')}
function news(){
 let my=new Set([...(S.watchlist||[]),...(S.holdings||[]).map(h=>h.asset)]),from=(Math.ceil(S.room.day/6)-1)*6+1;
 let items=S.news.filter(n=>(newsHorizon==='all'||n.horizon===newsHorizon)&& (newsScope==='all'||(newsScope==='today'?n.day===S.room.day:n.day>=from))&&(newsSector==='전체'||n.sector===newsSector||asset(n.sector)?.sector===newsSector||(n.related_assets||[]).some(id=>asset(id)?.sector===newsSector))&&(newsMode!=='mine'||(n.related_assets||[]).some(id=>my.has(id))||my.has(n.sector))&&(newsMode!=='followup'||n.kind==='followup')&&(!newsFocus||n.sector===newsFocus||(n.related_assets||[]).includes(newsFocus)));
 let today=S.news.filter(n=>n.day===S.room.day),sectors=['전체','기술','항공','식품','의료·제약','미래사업'];
 return `<div class="news-lead"><div><div class="eyebrow">THE HARU DAILY · ISSUE ${String(S.room.day).padStart(2,'0')}</div><h2>기업의 다음 장면을<br>읽는 시간.</h2><p>계획과 사실을 구분하고, 후속 보도와 분기 실적에서 확인하세요.</p></div><div class="issue-orbit"><strong>${today.length}</strong><span>TODAY'S STORIES</span></div></div>${npcPanel(true)}<div class="filter-bar"><div class="filter-left"><div class="seg">${[['today','오늘'],['quarter','이번 분기'],['all','모든 기사']].map(([k,v])=>`<button class="${newsScope===k?'active':''}" onclick="newsScope='${k}';render()">${v}</button>`).join('')}</div><select aria-label="뉴스 산업 필터" class="input" onchange="newsSector=this.value;render()">${sectors.map(k=>`<option value="${k}" ${newsSector===k?'selected':''}>${k==='전체'?'모든 산업':k}</option>`).join('')}</select></div><div class="chip-row">${[['all','전체 소식'],['mine','관심·보유 기업'],['followup','후속 보도']].map(([k,v])=>`<button class="chip ${newsMode===k?'active':''}" onclick="newsMode='${k}';render()">${v}</button>`).join('')}${newsFocus?`<button class="chip active" onclick="newsFocus='';render()">${esc(asset(newsFocus)?.name||newsFocus)} ×</button>`:''}</div></div><div class="filter-bar"><span class="sub">실적 영향 예상 시점</span><div class="chip-row">${[['all','모든 시점'],['short','단기'],['next_quarter','다음 분기'],['year_end','연말']].map(([k,v])=>`<button class="chip ${newsHorizon===k?'active':''}" onclick="filterHorizon('${k}')">${v}</button>`).join('')}</div></div><div class="news-layout-switch">${[['digest','핵심 5건'],['stories','사건별 보기'],['all','전체 기사']].map(([k,v])=>`<button class="chip ${newsLayout===k?'active':''}" onclick="newsLayout='${k}';render()">${v}</button>`).join('')}<span class="sub">${items.length}건의 기사 · 원래 자료는 모두 확인할 수 있어요.</span></div>${newsLayout==='stories'?projectBoard():''}${newsLayout==='digest'?digestCards(items):newsLayout==='stories'?storyCards(items):`<div class="news-grid">${newsCards(items)}</div>`}<p class="hint" style="margin-top:18px">기사에 대한 기대는 단기 가격에, 실제 사업 성과와 비용은 기사에 적힌 기간의 영업과 실적에 영향을 줍니다. 일정 지연과 예상 반전도 생길 수 있어요. 분기 실적은 6·12·18·24일차 시작에 공개되며 발표에 대한 반응은 같은 날 가격에 반영됩니다. 뉴스는 게임 규칙에 따라 생성되는 가상 기사입니다.</p>`
}
function closeModal(){let el=$('#modal-root');if(el)el.innerHTML='';activeArticle=null;document.body.style.overflow=''}
function showModal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="기사와 투자 정보">${html}</section></div>`;document.body.style.overflow='hidden';$('#modal-root .modal-x')?.focus()}
async function openArticle(id){
 let n=S.news.find(n=>n.id===id);if(!n)return toast('기사를 찾을 수 없어요.');let rel=(n.related_assets||[]).map(asset).filter(Boolean),related=S.news.filter(x=>x.event_id&&x.event_id===n.event_id).sort((a,b)=>a.day-b.day||a.id-b.id);
 showModal(`<div class="modal-titlebar"><div class="article-source sub">${esc(n.source||'하루경제')} · ${n.day}일차 ${certaintyTag(n)}</div><button class="modal-x" aria-label="닫기" onclick="closeModal()">${icon('close')}</button></div><h2>${esc(n.title)}</h2><div class="article-body">${esc(n.body)}</div>${metricsPanel(n)}${horizonDetails(n)}${n.lens?`<div class="explain-box"><b>${icon('book')} 읽으며 생각해 보기</b><p>${esc(n.lens)}</p></div>`:''}${related.length>1?`<div style="margin-top:24px"><div class="eyebrow">STORY TIMELINE</div><div class="trail" style="margin-top:16px">${related.map(x=>`<div class="trail-item"><small>${x.day}일차 · ${esc(x.certainty)}</small><b>${esc(x.title)}</b>${x.id!==n.id?`<button class="text-btn" onclick="openArticle(${x.id})">이 기사 읽기 →</button>`:''}</div>`).join('')}</div></div>`:''}${storyReports(related.length?related:[n])}<div class="modal-actions">${rel.slice(0,3).map(a=>`<button class="btn secondary sm" onclick="closeModal();detail('${a.id}')">${esc(a.name)} 분석</button>`).join('')}${S.role==='player'?`<button class="btn dark sm" onclick="noteFromNews(${n.id})">${icon('journal')} 투자 노트에 연결</button>`:''}${n.kind==='earnings'?`<button class="btn dark sm" onclick="go('earnings')">실적센터 보기</button>`:''}</div>`);
 activeArticle=id;
 if(S.role==='player'&&!S.demo&&!(S.read_ids||[]).includes(id)){try{await api('/news/'+id+'/read',{method:'POST'});S.read_ids=[...(S.read_ids||[]),id];if(S.learning)S.learning.read_count=S.read_ids.length}catch(e){toast(e.message)}}
}
function noteFromNews(id){let n=S.news.find(x=>x.id===id);journalAsset=(n.related_assets||[])[0]||'HBEL';evidenceDraft=id;closeModal();go('journal')}

function financialTiles(r){return `<div class="financial-grid">${[
 ['매출',billions(r.revenue),r.quarter?`이전 분기 대비 ${pct(r.revenue_growth)}`:'제품·서비스를 팔아 번 금액'],
 ['영업이익',billions(r.profit),r.quarter?`이전 분기 대비 ${pct(r.profit_growth)}`:'사업 비용을 빼고 남은 금액'],
 ['영업이익률',Number(r.margin).toFixed(1)+'%','매출 100원 중 남은 영업이익'],
 ['보유 현금',billions(r.cash),'회사가 보유한 현금'],
 ['부채',billions(r.debt),'회사가 갚아야 할 자금'],
 ['당초 예상 이익',billions(r.expected_profit),r.quarter?'실적 발표 전에 공개한 예상치':'게임 시작 시의 기준 이익']
 ].map(([k,v,h])=>`<div class="financial-tile"><span>${k}</span><strong>${v}</strong><small>${h}</small></div>`).join('')}</div>`}
function expectationsChart(r){let market=r.market_expected_profit??r.expected_profit,rows=[['당초 예상',r.expected_profit,''],['발표 직전 기대',market,'market'],['실제 발표',r.profit,'actual']],m=Math.max(...rows.map(x=>Math.abs(x[1])),1);return `<div class="compare-chart"><div class="section-title"><b style="font-size:12px">당초 예상 → 바뀐 기대 → 실제 결과</b>${reportBadge(r)}</div>${rows.map(([k,v,cls])=>`<div class="compare-line"><span>${k}</span><div class="compare-track"><div class="compare-fill ${cls}" style="width:${Math.abs(v)/m*100}%${v<0?';background:#b8958b':''}"></div></div><b>${billions(v)}</b></div>`).join('')}<p class="hint">당초 예상은 그대로 보관해요. 발표 직전 기대에는 공개된 사업 목표·준비 비용·일정·결과가 반영돼요. 가격은 이 기대와 실제 결과의 차이에도 반응해요.${rows.some(x=>x[1]<0)?' 막대 길이는 금액의 절댓값이며 음수는 손실이에요.':''}</p></div>`}
function reportTrend(id){let rr=(S.reports||[]).filter(r=>r.asset===id).sort((a,b)=>a.quarter-b.quarter);if(rr.length<2)return '<p class="hint">첫 분기 실적이 나오면 변화 추이가 표시됩니다.</p>';let W=600,H=165,l=45,t=22,b=30,w=520,vs=rr.flatMap(r=>[r.profit,r.expected_profit]),lo=Math.min(0,...vs),hi=Math.max(1,...vs),y=v=>t+(hi-v)/Math.max(1,hi-lo)*(H-t-b),step=w/rr.length;return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;max-height:190px" role="img" aria-label="분기별 실제 영업이익과 사전 예상 영업이익 비교"><line x1="${l}" x2="${l+w}" y1="${y(0)}" y2="${y(0)}" stroke="#dbe5d3"/>${rr.map((r,i)=>{let x=l+step*i+step/2;return `<rect x="${x-20}" y="${Math.min(y(0),y(r.expected_profit))}" width="16" height="${Math.max(1,Math.abs(y(0)-y(r.expected_profit)))}" fill="#d5e1cb" rx="2"/><rect x="${x+2}" y="${Math.min(y(0),y(r.profit))}" width="16" height="${Math.max(1,Math.abs(y(0)-y(r.profit)))}" fill="#6f9e6a" rx="2"/><text x="${x}" y="${H-8}" text-anchor="middle" font-size="10" fill="#8b9f7d">${r.quarter?r.quarter+'분기':'기준'}</text><title>${r.quarter||'기준'}분기 예상 ${r.expected_profit}억원 / 실제 ${r.profit}억원</title>`}).join('')}</svg><p class="hint center">연한 막대 · 당초 예상 이익　진한 막대 · 실제 이익</p>`}
function earnings(){
 const available=[...new Set((S.reports||[]).map(r=>r.quarter))].sort((a,b)=>b-a),q=earningsQ!==null&&available.includes(+earningsQ)?+earningsQ:available[0]||0;
 const rr=(S.reports||[]).filter(r=>r.quarter===q),r=rr.find(x=>x.asset===earningsAsset)||rr[0],a=asset(r?.asset||earningsAsset);
 if(!r)return emptyState('기업 재무정보를 준비하고 있어요.');
 let forecast=forecastFor(a.id,Math.min(4,q+1)),links=r.evidence_ids.map(id=>S.news.find(n=>n.id===id)).filter(Boolean);
 return `<div class="earnings-intro"><div><div class="eyebrow">BUSINESS PERFORMANCE</div><h2>이야기 다음에는, 숫자.</h2><p>기업의 성적표와 발표 전 기대를 나란히 비교해 보세요.</p></div>${calendarCards()}</div><div class="filter-bar"><div class="seg">${available.map(n=>`<button class="${q===n?'active':''}" onclick="earningsQ=${n};render()">${n?n+'분기 실적':'기준 실적'}</button>`).join('')}</div><select class="input" style="width:215px" aria-label="분석할 기업" onchange="earningsAsset=this.value;render()">${S.assets.filter(x=>x.type==='stock').map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)} · ${esc(x.sector)}</option>`).join('')}</select></div>${q===0?`<div class="notice" style="margin-bottom:18px">첫 실적 발표 전입니다. 아래 기준 실적과 현재 공개된 예상치를 살펴보고, 뉴스의 변화가 어떤 결과로 이어질지 생각해 보세요.</div>`:''}<div class="research-layout"><div class="stack"><div class="card"><div class="report-company">${companyAvatar(a)}<div><h2>${esc(a.name)}</h2><p class="sub">${a.id} · ${esc(a.sector)} · ${q?q+'분기 발표':'시작 기준'}</p></div><div class="right">${smallLink('기업 분석',`detail('${a.id}')`)}</div></div>${financialTiles(r)}${q?expectationsChart(r):`<div class="explain-box"><b>실적 발표 전에 공개된 ${forecast?.quarter||1}분기 예상</b><p>매출 ${billions(forecast?.revenue)} · 영업이익 ${billions(forecast?.profit)}<br>예상은 결과를 보장하지 않아요. 이후 뉴스와 실제 발표를 비교해 보세요.</p></div>`}${q<4?currentEstimatePanel(a.id,q+1):''}<div class="explain-box"><b>${icon('search')} 실적을 이렇게 읽어 보세요</b><p>${esc(r.explanation)}</p>${q?`<p>${esc(r.outlook)}</p>`:''}</div><div class="line"></div><h3>분기별 영업이익 추이</h3>${reportTrend(a.id)}</div><div class="card"><div class="section-title"><h2>${q?q+'분기 기업 실적 비교':'20개 기업 기준 실적'}</h2><span class="sub">단위: 가상 억원</span></div><div class="tablewrap"><table class="financial-table"><thead><tr><th>기업</th><th>매출</th><th>영업이익</th><th>이익률</th><th>발표 직전 기대 대비</th></tr></thead><tbody>${rr.map(x=>`<tr class="click-row" tabindex="0" onclick="earningsAsset='${x.asset}';render()" onkeydown="if(event.key==='Enter'){earningsAsset='${x.asset}';render()}"><td><b>${esc(asset(x.asset).name)}</b></td><td>${number(x.revenue)}</td><td>${number(x.profit)}</td><td>${Number(x.margin).toFixed(1)}%</td><td>${q?reportBadge(x):'<span class="sub">기준</span>'}</td></tr>`).join('')}</tbody></table></div></div></div><div class="stack"><div class="card"><div class="section-title"><h2>이번 실적과 연결된 단서</h2>${icon('link')}</div><p class="sub">분기 중 해당 기업에 어떤 소식이 있었나요?</p>${links.length?newsCards(links,true):emptyState('분기 중 기업 뉴스가 쌓이면 이곳에서 함께 확인할 수 있어요.')}</div><div class="research-prompt"><div class="eyebrow">THINK BEFORE YOU INVEST</div><p>매출과 이익이 함께 늘었나요?<br>기대했던 것보다 더 잘했나요?<br>부채와 현금은 어떻게 변했나요?</p><button class="text-btn" style="padding:12px 0 0" onclick="journalAsset='${a.id}';go('${S.role==='admin'?'players':'journal'}')">${S.role==='admin'?'학생의 판단 과정 살펴보기':'이 기업에 대한 내 생각 남기기'} ${icon('arrow')}</button></div>${forecast&&q>0&&q<4?`<div class="card"><div class="eyebrow">NEXT QUARTER EXPECTATION</div><h3 style="margin-top:10px">다음 분기 시장 예상</h3><div class="flex sub"><span>매출</span><b>${billions(forecast.revenue)}</b></div><div class="flex sub" style="margin-top:8px"><span>영업이익</span><b>${billions(forecast.profit)}</b></div><p class="hint">${forecast.published_day}일차 공개 · 이후 결과와 비교할 기준</p></div>`:''}</div></div><p class="hint" style="margin-top:18px">${q===0?'기준 실적은 게임을 시작할 때 제공되는 비교 자료입니다. ':''}모든 기업과 재무 수치는 교육용 가상 데이터입니다. 분기 실적은 6·12·18·24일차 시작에 공개되며, 가격 반응도 같은 날 반영됩니다.</p>`
}

function market(){
 let list=S.assets.filter(a=>(marketFilter==='all'||marketFilter==='watch'?(marketFilter!=='watch'||(S.watchlist||[]).includes(a.id)):a.type===marketFilter)&&(marketSector==='전체'||a.sector===marketSector)&&(!marketSearch||a.name.includes(marketSearch)||a.id.toLowerCase().includes(marketSearch.toLowerCase())));
 return `<div class="card" style="margin-bottom:20px"><div class="section-title"><h2>산업별 오늘의 흐름</h2><span class="sub">섹터 ETF 등락률</span></div>${sectorBoard()}</div><div class="filter-bar"><div class="filter-left"><div class="chip-row">${[['all','전체'],['stock','기업 주식'],['etf','ETF'],['bond','채권'],['gold','금'],['watch','☆ 관심 상품']].map(([k,v])=>`<button class="chip ${marketFilter===k?'active':''}" onclick="marketFilter='${k}';marketSector='전체';render()">${v}</button>`).join('')}</div></div><div class="filter-left" style="width:auto"><select class="input" aria-label="상품 산업 필터" onchange="marketSector=this.value;render()"><option value="전체">모든 산업</option>${['기술','항공','식품','의료·제약','미래사업'].map(k=>`<option value="${k}" ${marketSector===k?'selected':''}>${k}</option>`).join('')}</select><input aria-label="기업 검색" class="input" placeholder="기업 이름 검색" value="${esc(marketSearch)}" oninput="marketSearch=this.value;renderMarketResults()" id="market-search"></div></div><div class="card" id="market-results">${marketTable(list)}</div><p class="hint">현재 가격으로 즉시 거래돼요. 가격은 하루에 한 번 갱신되며, 투자 이유를 함께 남깁니다.</p>`
}
function marketTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>상품</th><th>현재가</th><th>오늘 변동</th><th>최근 매출</th><th>영업이익률</th><th>실적</th><th>관심</th></tr></thead><tbody>${list.map(a=>{let r=latestReport(a.id);return `<tr style="cursor:pointer" onclick="detail('${a.id}')" tabindex="0" onkeydown="if(event.key==='Enter')detail('${a.id}')"><td><div class="flex" style="justify-content:flex-start;gap:11px">${companyAvatar(a)}<div><b>${esc(a.name)}</b><div class="sub" style="font-size:10px">${a.id} · ${risk[a.risk]}</div></div></div></td><td><b>${money(a.price)}</b></td><td class="${a.change>=0?'up':'down'}">${pct(a.change)}</td><td>${r?billions(r.revenue):'—'}</td><td>${r?Number(r.margin).toFixed(1)+'%':'—'}</td><td>${r?.quarter?reportBadge(r):r?'<span class="tag">기준 실적</span>':'<span class="sub">금융상품</span>'}</td><td><button class="watch-star ${(S.watchlist||[]).includes(a.id)?'on':''}" aria-label="${esc(a.name)} 관심 ${S.watchlist?.includes(a.id)?'해제':'등록'}" aria-pressed="${(S.watchlist||[]).includes(a.id)}" onclick="event.stopPropagation();toggleWatch('${a.id}')">${(S.watchlist||[]).includes(a.id)?'★':'☆'}</button></td></tr>`}).join('')}</tbody></table></div>`:emptyState('조건에 맞는 상품이 없어요.')}
function renderMarketResults(){const list=S.assets.filter(a=>(marketFilter==='all'||(marketFilter==='watch'?(S.watchlist||[]).includes(a.id):a.type===marketFilter))&&(marketSector==='전체'||a.sector===marketSector)&&(!marketSearch||a.name.includes(marketSearch)||a.id.toLowerCase().includes(marketSearch.toLowerCase())));$('#market-results').innerHTML=marketTable(list)}
async function toggleWatch(id){if(S.role!=='player')return toast('관심 목록은 학생 계정에서 관리해요.');try{let enabled=!(S.watchlist||[]).includes(id);await api('/watchlist',{method:'POST',body:{asset:id,enabled}});S.watchlist=enabled?[...(S.watchlist||[]),id]:S.watchlist.filter(x=>x!==id);render()}catch(e){toast(e.message)}}
function detailView(){
 const a=asset(selected),r=latestReport(selected),links=S.news.filter(n=>n.sector===selected||(n.related_assets||[]).includes(selected)).filter(n=>n.kind!=='earnings').slice(0,5);
 let html=baseDetailView();
 const evidence=evidenceSelector('trade-evidence',selected);
 html=html.replace('<label>왜 이 상품을 선택했나요?</label>',`<div class="order-evidence"><label>판단에 참고한 뉴스 <span class="sub">선택 · 최대 5건</span></label>${evidence}</div><label>왜 이 상품을 선택했나요?</label>`);
 return `<div id="trade-meta" data-asset="${selected}"></div><div class="quarter-strip"><span>${a.type==='stock'?'기업 리서치':'상품 분석'}</span><span>${esc(a.sector)} · ${risk[a.risk]}</span>${S.role==='player'?`<button class="text-btn" onclick="toggleWatch('${selected}')">${(S.watchlist||[]).includes(selected)?'★ 관심 기업':'☆ 관심 목록에 담기'}</button>`:''}${a.type==='stock'?smallLink('전체 분기 실적',`earningsAsset='${selected}';go('earnings')`):''}</div>${html}<div style="height:20px"></div>${r?`<div class="research-layout"><div class="card"><div class="section-title"><h2>${r.quarter?r.quarter+'분기':'기준'} 기업 성적표</h2><span class="sub">단위 · 가상 억원</span></div>${financialTiles(r)}${r.quarter?expectationsChart(r):`<p class="hint">다음 실적 발표 전 예상 매출 ${billions(forecastFor(selected,1)?.revenue)} · 예상 영업이익 ${billions(forecastFor(selected,1)?.profit)}</p>`}<div class="explain-box"><b>실적에서 무엇을 확인할까요?</b><p>${esc(r.explanation)}</p></div></div><div class="card"><div class="section-title"><h2>이 기업의 뉴스 흐름</h2>${smallLink('더 보기',`newsFocus='${selected}';newsScope='all';go('news')`)}</div>${newsCards(links,true)}${projectBoard(selected)}</div></div>`:links.length?`<div class="card"><h2>관련 뉴스</h2>${newsCards(links,true)}</div>`:''}`
}
function evidenceSelector(id,aid,preselected=null){let relevant=S.news.filter(n=>n.kind!=='briefing'&&(n.sector===aid||n.sector===asset(aid)?.sector||n.sector==='전체'||n.related_assets?.includes(aid))).slice(0,14);return relevant.length?`<div class="evidence-checks" id="${id}">${relevant.map(n=>`<label class="evidence-option"><input type="checkbox" value="${n.id}" ${preselected===n.id?'checked':''} ${S.role==='admin'?'disabled':''}><span><span style="color:#a2b098;font-size:9px">${n.day}일차 · ${esc(n.certainty||'기사')}</span><br>${esc(n.title)}</span></label>`).join('')}</div>`:`<div class="notice">아직 관련 기사가 없어요. 기업 정보나 상품 구조를 바탕으로 판단해 보세요.</div>`}
function pickedEvidence(id){return [...document.querySelectorAll('#'+id+' input:checked')].map(el=>+el.value)}
async function place(){
 let qty=+$('#qty').value,reason=$('#reason').value.trim(),evidence_ids=pickedEvidence('trade-evidence');if(!Number.isInteger(qty)||qty<1)return toast('수량은 1 이상의 정수로 입력하세요.');if(reason.length<2)return toast('투자 이유를 2자 이상 적어주세요.');if(evidence_ids.length>5)return toast('근거 기사는 최대 5건까지 선택해요.');
 if(!confirm(`${asset(selected).name} ${qty}주를 ${money(asset(selected).price*qty)}에 ${currentSide==='buy'?'매수':'매도'}할까요?`))return;
 try{let r=await api('/orders',{method:'POST',body:{asset:selected,side:currentSide,qty,reason,evidence_ids}});toast(r.message);tab='portfolio';await refresh()}catch(e){toast(e.message)}
}

function journal(){
 let d=S,l=d.learning||{},a=asset(journalAsset)||asset('HBEL'),notes=d.notes||[],canWrite=S.role==='player'&&S.room.phase==='trading';
 return `<div class="learning-stats">${[['열람한 기사',l.read_count||0],['근거 연결 거래',l.evidence_trades||0],['투자 가설',l.note_count||0],['작성한 돌아보기',l.reflection_count||0]].map(([k,v])=>`<div class="learning-stat"><span>${k}</span><b>${v}<span style="font-size:10px;margin-left:4px">건</span></b></div>`).join('')}</div><div class="research-layout"><div class="stack">${notes.length?notes.map(n=>{let a=asset(n.asset),diff=n.entry_price?(a.price/n.entry_price-1)*100:0;return `<article class="note-card"><div class="note-meta"><span>${n.day}일차의 생각 · ${esc(n.horizon)}</span><span class="tag">${esc(a.name)}</span></div><h3>${esc(n.thesis)}</h3><div class="note-risk"><b>생각한 위험</b>　${esc(n.risk)}</div><div class="note-evidence">${n.evidence_ids.map(id=>{let x=S.news.find(v=>v.id===id);return x?`<button onclick="openArticle(${id})">${icon('link')} ${esc(x.title)}</button>`:''}).join('')}</div><div class="flex" style="margin-top:18px"><span class="sub">기록 당시 ${money(n.entry_price)} → 현재 ${money(a.price)} <b class="${diff>=0?'up':'down'}">${pct(diff)}</b></span>${S.role==='player'?`<button class="btn secondary sm" onclick="reflectionModal(${n.id})">${n.reflection?'돌아보기 수정':'돌아보기 쓰기'}</button>`:''}</div>${n.reflection?`<div class="reflection-box"><b>결과를 보고 배운 점</b><br>${esc(n.reflection)}</div>`:''}<p class="hint" style="margin-bottom:0">가격 변화는 가설을 기록한 시점과 비교한 값이며, 실제 거래 수익률과는 다를 수 있어요.</p></article>`}).join(''):`<div class="card"><div class="eyebrow">YOUR FIRST THESIS</div><h2 style="margin:12px 0">좋은 판단은 기록에서 시작돼요.</h2><p class="sub">읽은 뉴스와 예상, 걱정거리를 남겨 보세요.<br>거래를 하지 않고 기다리는 이유도 기록할 수 있어요.</p><div class="research-prompt"><p>“주문량이 늘어난다는 뉴스를 읽었다.<br>매출은 늘겠지만, 비용도 늘 수 있어 이익률을 확인하겠다.”</p></div></div>`}</div><div><div class="card"><div class="eyebrow">NEW INVESTMENT THESIS</div><h2 style="margin:10px 0 0">나의 판단을 남겨요.</h2><p class="sub" style="margin-top:8px">처음 생각은 저장한 뒤 바뀌지 않아요.<br>이후 배운 점은 돌아보기에 덧붙일 수 있어요.</p><form onsubmit="event.preventDefault();saveNote()"><label for="note-asset">살펴보는 기업·상품</label><select class="input" id="note-asset" onchange="journalAsset=this.value;evidenceDraft=null;render()">${S.assets.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><label for="note-thesis">어떤 일이 일어날 것 같나요?</label><textarea class="input" id="note-thesis" minlength="5" maxlength="700" rows="3" placeholder="뉴스와 기업 정보를 연결해 예상해 보세요." oninput="noteDraft.thesis=this.value" ${!canWrite?'disabled':''} required>${esc(noteDraft.thesis)}</textarea><label for="note-risk">생각과 다르게 될 수 있는 점은?</label><textarea class="input" id="note-risk" minlength="2" maxlength="500" rows="2" placeholder="비용 증가, 계획 지연, 경쟁 심화…" oninput="noteDraft.risk=this.value" ${!canWrite?'disabled':''} required>${esc(noteDraft.risk)}</textarea><label for="note-horizon">언제 다시 확인할까요?</label><select class="input" id="note-horizon" onchange="noteDraft.horizon=this.value"><option>다음 실적 발표까지</option><option>후속 뉴스가 나올 때</option><option>2~3일 뒤</option><option>게임 종료 시점</option></select><label>판단의 근거 기사 <span class="sub">선택 · 최대 5건</span></label>${evidenceSelector('note-evidence',a.id,evidenceDraft)}<button class="btn dark" type="submit" style="width:100%;margin-top:20px" ${!canWrite?'disabled':''}>${icon('plus')} 투자 노트 저장</button></form>${!canWrite?'<p class="hint">새 가설은 거래일 중에 기록할 수 있어요. 기존 가설의 돌아보기는 언제든 작성할 수 있어요.</p>':''}</div><div class="notice" style="margin-top:14px">열람 수와 기록 수는 학습 활동의 참고 정보입니다. 수익이나 기록 개수만으로 판단의 질을 평가하지 않아요.</div></div></div>`
}
async function saveNote(){let evidence_ids=pickedEvidence('note-evidence');if(evidence_ids.length>5)return toast('근거 기사는 최대 5건까지 선택해요.');try{await api('/notes',{method:'POST',body:{asset:$('#note-asset').value,thesis:$('#note-thesis').value,risk:$('#note-risk').value,horizon:$('#note-horizon').value,evidence_ids}});evidenceDraft=null;noteDraft={thesis:'',risk:'',horizon:'다음 실적 발표까지'};toast('처음 생각을 저장했어요. 다음 실적에서 확인해 보세요.');await refresh()}catch(e){toast(e.message)}}
function reflectionModal(id){let n=S.notes.find(n=>n.id===id);if(!n)return;showModal(`<div class="modal-titlebar"><span class="eyebrow">REFLECT & LEARN</span><button class="modal-x" aria-label="닫기" onclick="closeModal()">${icon('close')}</button></div><h2>내 판단을 다시 살펴봐요.</h2><div class="notice"><b>${n.day}일차의 생각</b><br>${esc(n.thesis)}</div><form onsubmit="event.preventDefault();saveReflection(${id})"><label for="reflection">무엇이 맞았고, 무엇을 놓쳤나요?</label><textarea class="input" id="reflection" rows="5" maxlength="1000" minlength="5" placeholder="예상과 달랐던 이유와 다음에 확인할 점을 적어 보세요." required>${esc(n.reflection)}</textarea><div class="modal-actions"><button type="submit" class="btn dark">돌아보기 저장</button></div></form>`)}
async function saveReflection(id){try{await api('/notes/'+id,{method:'PATCH',body:{reflection:$('#reflection').value}});closeModal();toast('배운 점을 저장했어요.');await refresh()}catch(e){toast(e.message)}}

function teacherHome(){
 let ps=S.participants||[],reads=ps.reduce((n,p)=>n+p.read_count,0),notes=ps.reduce((n,p)=>n+p.note_count,0),ready=ps.filter(p=>p.day_ready).length;
 return `<div class="overview">${stat('오늘의 선택 완료',`${ready} <span style="font-size:18px;color:#9fc2ae">/ ${ps.length}명</span>`,S.all_ready?'모든 학생이 오늘 선택을 마쳤어요.':'학생별 완료 현황을 확인하고 장을 마감하세요.',true,'people')}${stat('우리 반 기사 열람',number(reads)+'건','공개된 기사를 열어 본 누적 횟수',false,'news')}${stat('작성한 투자 가설',number(notes)+'건',`돌아보기 ${ps.reduce((n,p)=>n+p.reflection_count,0)}건 · 근거 연결 거래 ${ps.reduce((n,p)=>n+p.evidence_trades,0)}건`,false,'journal')}</div>${npcPanel()}<div class="dashboard-grid"><div class="stack"><div class="card"><div class="section-title"><h2>오늘의 수업 진행</h2><span class="tag">${S.room.day}일차 / 24일</span></div><div class="notice">뉴스 읽기 → 기업 정보·예상 실적 비교 → 투자 또는 기다리기 → 판단 기록 → 하루 마감</div><div class="line"></div><div class="flex wrap"><div><b style="font-size:13px">${S.room.phase==='trading'?'학생들의 판단을 기다리고 있어요.':S.room.phase==='closed'?'오늘 장이 마감되었습니다.':'가상의 1년을 마쳤습니다.'}</b><div class="sub">${S.room.phase==='trading'?'완료 현황을 확인한 뒤 선생님이 장을 마감해 주세요.':S.room.phase==='closed'?'다음 거래일을 시작하면 새 뉴스와 가격이 공개돼요.':'분기 실적과 학생들의 돌아보기를 함께 읽어 보세요.'}</div></div>${S.room.phase==='trading'?'<button class="btn dark" onclick="adminAction(\'close\')">오늘 장 마감</button>':S.room.phase==='closed'?'<button class="btn dark" onclick="adminAction(\'next\')">다음 날 시작 →</button>':'<span class="badge">최종 결산</span>'}</div><div class="ready-list" style="margin-top:18px">${ps.map(p=>`<button class="chip ${p.day_ready?'active':''}" onclick="tab='preview';loadPreview(${p.id})">${p.day_ready?'✓':'○'} ${esc(p.name)}</button>`).join('')||'<span class="sub">학생들이 참가하면 이곳에 표시돼요.</span>'}</div></div><div class="card"><div class="section-title"><h2>선생님도 함께 읽는 오늘 뉴스</h2>${smallLink('뉴스룸',"go('news')")}</div>${newsCards(selectHighlights(S.news.filter(n=>n.day===S.room.day)),true)}</div><div class="card"><div class="section-title"><h2>우리 반의 판단 과정</h2>${smallLink('학생별 확인',"go('players')")}</div>${ps.length?ps.slice(0,5).map(p=>`<div class="focus-row" onclick="tab='preview';loadPreview(${p.id})"><div class="avatar">${esc(p.name.slice(0,1))}</div><div class="desc"><b>${esc(p.name)}</b><p>기사 ${p.read_count} · 가설 ${p.note_count} · 돌아보기 ${p.reflection_count}</p></div><div class="right"><span class="${p.day_ready?'badge':'tag'}">${p.day_ready?'선택 완료':'선택 중'}</span></div></div>`).join(''):emptyState('QR 코드로 학생을 초대해 보세요.')}</div></div><div class="stack"><div class="card"><div class="section-title"><h2>분기 실적 일정</h2>${icon('calendar')}</div>${calendarCards()}<p class="hint">매 6번째 거래일 시작에 20개 기업의 실적이 동시에 공개되고, 발표에 대한 가격 반응도 함께 반영됩니다.</p><button class="btn secondary sm" onclick="go('earnings')">실적센터 열기 ${icon('arrow')}</button></div><div class="card"><div class="section-title"><h2>학생 참가</h2><span class="tag">${esc(S.room.code)}</span></div><div id="shareBox"><p class="sub">학생 참가 QR을 준비하고 있어요.</p></div></div><div class="research-prompt"><div class="eyebrow">DISCUSSION PROMPT</div><p>“매출은 늘었는데 이익은 줄어든 기업이 있나요?”<br>“좋은 실적에도 기대보다 부족할 수 있을까요?”</p></div></div></div>`
}
function participants(){let ps=S.participants||[];return `<div class="notice" style="margin-bottom:20px">학생의 수익과 판단 과정을 함께 살펴보세요. 기사 열람 수는 이해도를 뜻하지 않으며, 기록 개수와 수익률만으로 학습을 평가하지 않습니다.</div><div class="card"><div class="section-title"><h2>학생별 금융 활동과 학습 기록</h2><span class="sub">${ps.length}명 참가</span></div>${ps.length?`<div class="tablewrap"><table><thead><tr><th>학생</th><th>오늘 선택</th><th>총자산</th><th>기사 열람</th><th>근거 연결 거래</th><th>투자 가설</th><th>돌아보기</th><th>살펴보기</th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td><span class="${p.day_ready?'badge':'tag'}">${p.day_ready?'완료':'선택 중'}</span></td><td>${money(p.net)}</td><td>${p.read_count}건</td><td>${p.evidence_trades}건</td><td>${p.note_count}건</td><td>${p.reflection_count}건</td><td><button class="btn secondary sm" onclick="tab='preview';loadPreview(${p.id})">학생 화면</button> <button class="btn ghost sm" onclick="cashPrompt(${p.id})">현금 조정</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('아직 참가한 학생이 없어요.')}</div>`}
function cashPrompt(id){let p=S.participants.find(x=>x.id===id);if(p)changeCash(id,p.name)}
async function loadPreview(pid){if(!pid){previewPid=null;previewData=null;return render()}try{previewPid=+pid;previewData=await api('/admin/student/'+previewPid);previewTab='home';render()}catch(e){toast(e.message)}}
function adminPreview(){
 let names=S.participants||[],chooser=`<div class="card" style="margin-bottom:18px"><div class="flex wrap"><div><h2>학생이 보는 화면 그대로</h2><p class="sub no-margin">실제 잔액과 보유 상품, 기사 열람·투자 노트를 읽기 전용으로 확인해요.</p></div><select class="input" aria-label="미리볼 학생" style="width:200px" onchange="loadPreview(this.value)"><option value="">학생 선택</option>${names.map(p=>`<option value="${p.id}" ${+previewPid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div>`;
 if(!previewData)return chooser+emptyState(names.length?'살펴볼 학생을 선택해 주세요.':'학생이 참가하면 실제 학생 화면을 이곳에서 확인할 수 있어요.');
 let saved=S,pv=previewData;S={...S,...pv,role:'admin'};let menu=`<div class="chip-row" style="margin-bottom:18px">${studentMenu.map(([k,v])=>`<button class="chip ${previewTab===k?'active':''}" onclick="go('${k}')">${v}</button>`).join('')}</div>`,body='';try{body=({home:playerHome,news,earnings,market,portfolio,journal,bank,orders,detail:detailView}[previewTab]||playerHome)()}finally{S=saved}
 return chooser+`<div class="preview-banner">${icon('eye')} ${esc(pv.player.name)} 학생의 현재 화면 · 교사 읽기 전용</div>`+menu+body
}
function adminOrders(){return `<div class="card"><div class="section-title"><h2>거래와 투자 근거</h2><span class="sub">최근 60건</span></div>${S.all_orders.length?`<div class="tablewrap"><table><thead><tr><th>학생</th><th>상품</th><th>거래</th><th>수량</th><th>선택 이유</th><th>참고 기사</th></tr></thead><tbody>${S.all_orders.map(o=>{let ids=[];try{ids=JSON.parse(o.evidence_ids||'[]')}catch{}return `<tr><td>${esc(o.name)}</td><td>${esc(asset(o.asset)?.name||o.asset)}</td><td>${o.side==='buy'?'매수':'매도'}</td><td>${o.qty}</td><td style="white-space:normal;min-width:180px;max-width:350px;line-height:1.8">${esc(o.reason)}</td><td>${ids.length?ids.map(id=>`<button class="text-btn" onclick="openArticle(${id})">기사 #${id} ↗</button>`).join(''):'—'}</td></tr>`}).join('')}</tbody></table></div>`:emptyState('학생이 거래하면 선택 이유와 참고 기사를 함께 볼 수 있어요.')}</div>`}
async function adminAction(op){let pending=(S.participants||[]).filter(p=>!p.day_ready).length;let message=op==='close'?`${pending?`아직 ${pending}명의 학생이 선택 중입니다. `:''}${S.room.day}일차 장을 마감할까요?`:`${S.room.day+1}일차를 시작할까요?${[6,12,18,24].includes(S.room.day+1)?' 이번 거래일에는 분기 실적이 공개되고 가격에 반영됩니다.':''}`;if(!confirm(message))return;try{let r=await api('/admin/'+op,{method:'POST'});toast(op==='close'?'오늘 장을 마감했어요.':`${r.day}일차를 시작했어요.`);await refresh()}catch(e){toast(e.message)}}
function bank(){return baseBank()+`<div class="notice" style="margin-top:18px">24일 예금의 만기 수익률은 10%입니다. 같은 날 가입 후 중도해지하면 이자가 없어요. 아래 진행률 비교선은 실제 중도해지 이자와 다릅니다.</div>`+benchmarkCard()}

async function refresh(quiet=false){
 if(S?.demo){render();return}if(refreshing)return;refreshing=true;
 try{let next=await api('/state');let dayChanged=S&&next.room.day!==S.room.day;S=next;if(S.role==='admin'&&tab==='preview'&&previewPid)previewData=await api('/admin/student/'+previewPid);if(currentView()==='detail'&&(dayChanged||!history.length))history=await api('/history/'+selected);render();if(dayChanged)toast(`${S.room.day}일차가 시작됐어요.${[6,12,18,24].includes(S.room.day)?' 분기 실적이 공개되었습니다.':''}`)}
 catch(e){if(e.message.includes('로그인')){token='';localStorage.removeItem('haru_token');S=null;render()}else if(!quiet)toast(e.message)}finally{refreshing=false}
}
function render(){
 if(!S){$('#app').innerHTML=authView();return}
 if($('#qty')&&$('#trade-meta'))tradeDrafts[$('#trade-meta').dataset.asset]={qty:$('#qty').value,reason:$('#reason').value,ids:pickedEvidence('trade-evidence')};
 $('#app').innerHTML=head();let view=S.role==='admin'?({home:teacherHome,preview:adminPreview,players:participants,news,earnings,market,detail:detailView,orders:adminOrders,admin:adminPanel}[tab]||teacherHome):({home:playerHome,market,detail:detailView,bank,portfolio,news,orders,earnings,journal}[tab]||playerHome);
 $('#page').innerHTML=view();if(currentView()==='detail'&&tradeDrafts[selected]&&$('#qty')){let d=tradeDrafts[selected];$('#qty').value=d.qty;$('#reason').value=d.reason;document.querySelectorAll('#trade-evidence input').forEach(el=>el.checked=d.ids.includes(+el.value));updateOrderTotal()}if(currentView()==='journal'&&$('#note-horizon'))$('#note-horizon').value=noteDraft.horizon;if(currentView()==='bank'&&(S.role==='player'||previewData))bankCalc();if(S.role==='admin'&&tab==='home')loadShare();
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const all=[...$('#modal-root .modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
if(token){$('#app').innerHTML='<div class="loading"><div><div class="pulse"></div>투자 연구소에 연결하고 있어요.</div></div>';refresh()}else render();
setInterval(()=>{if(!token||!S||S.demo||document.visibilityState!=='visible'||$('#modal-root')?.children.length)return;let el=document.activeElement;if(el&&['INPUT','SELECT','TEXTAREA'].includes(el.tagName))return;refresh(true)},12000);
